    verifications.run();
    reset(ss);
    setUpEndpointForRecovery(endpoint, ei, si, bi, ii);
    RMMessage m = mock(RMMessage.class);
    verifications = setUpRecoverReliableEndpoint(endpoint, conduit, ss, ds, m);
    manager.recoverReliableEndpoint(endpoint, conduit);
    verifications.run();
}

