public void setUp() throws Exception {
    bus = BusFactory.newInstance().createBus();
    BindingFactoryManager bfm = bus.getExtension(BindingFactoryManager.class);
    BindingFactory bf = mock(BindingFactory.class);
    Binding binding = mock(Binding.class);
    when(bf.createBinding(null)).thenReturn(binding);
    when(binding.getInFaultInterceptors()).thenReturn(new ArrayList<Interceptor<? extends Message>>());
    when(binding.getOutFaultInterceptors()).thenReturn(new ArrayList<Interceptor<? extends Message>>());
    bfm.registerBindingFactory("http://schemas.xmlsoap.org/wsdl/soap/", bf);
    String ns = "http://apache.org/hello_world_soap_http";
    WSDLServiceFactory factory = new WSDLServiceFactory(bus, getClass().getResource("/org/apache/cxf/jaxb/resources/wsdl/hello_world.wsdl").toString(), new QName(ns, "SOAPService"));
    service = factory.create();
